const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const port = ee.Geometry.Point([-62.27, -38.78]);
  const aoi = port.buffer(10000); // 10 km radius

  const date1 = '2025-01-30';
  const date2 = '2025-03-11';

  // 2. Data Acquisition & Check
  // Sentinel-1 SAR data for flood detection
  const s1_jan = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(aoi)
    .filterDate('2025-01-28', '2025-02-01')
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const s1_mar = ee.ImageCollection('COPERNICUS/S1_GRD')
    .filterBounds(aoi)
    .filterDate('2025-03-09', '2025-03-13')
    .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'))
    .select('VV');

  const count_jan = s1_jan.size().getInfo();
  const count_mar = s1_mar.size().getInfo();

  console.log(`January images: ${count_jan}, March images: ${count_mar}`);

  if (count_jan === 0 || count_mar === 0) {
    console.log('No Sentinel-1 data available for one or both dates.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Water detection using SAR backscatter threshold
  const img_jan = s1_jan.median();
  const img_mar = s1_mar.median();

  // Water detection: VV < -15 dB typically indicates water
  const water_jan = img_jan.lt(-15);
  const water_mar = img_mar.lt(-15);

  // 4. Calculate inundation area
  const scale = 10; // Sentinel-1 resolution

  const stats_jan = water_jan.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const stats_mar = water_mar.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const count_pixels_jan = water_jan.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  });

  const water_pixels_jan = stats_jan.get('VV').getInfo();
  const water_pixels_mar = stats_mar.get('VV').getInfo();
  const total_pixels_jan = count_pixels_jan.get('VV').getInfo();

  console.log(`Total pixels analyzed: ${total_pixels_jan}`);

  if (total_pixels_jan === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Validation & Final Answer
  if (water_pixels_jan === null || water_pixels_mar === null || 
      isNaN(water_pixels_jan) || isNaN(water_pixels_mar)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert to area (pixels * scale^2)
  const area_jan_km2 = (water_pixels_jan * scale * scale) / 1e6;
  const area_mar_km2 = (water_pixels_mar * scale * scale) / 1e6;

  console.log(`January 30, 2025 inundation: ${area_jan_km2.toFixed(3)} km2 (${water_pixels_jan} pixels)`);
  console.log(`March 11, 2025 inundation: ${area_mar_km2.toFixed(3)} km2 (${water_pixels_mar} pixels)`);
  console.log(`Change: ${(area_mar_km2 - area_jan_km2).toFixed(3)} km2`);

  if (area_mar_km2 > area_jan_km2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
